parts.text:
{
  "references": [
    {
      "id": "R1",
      "summary_ko": "배경에 있는 여성의 손이 마우스 주변에서 이상하게 움직임"
    },
    {
      "id": "R2",
      "summary_ko": "여성이 의미 없는 긴 단어들의 나열을 말함"
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "말하는 동안 입과 치아에 미세한 왜곡 및 부자연스러운 변형 아티팩트가 나타남"
    },
    {
      "id": "C2",
      "summary_ko": "하단 가장자리의 손이 주기적으로 왜곡되며 옷 및 프레임 경계와 불분명하게 섞임"
    },
    {
      "id": "C3",
      "summary_ko": "발화 전환 중 화자의 입, 입술, 치아 주변에 미세한 왜곡 및 모핑이 발생함"
    },
    {
      "id": "C4",
      "summary_ko": "배경의 사무실 직원들이 긴 시간 동안 부자연스럽게 정지해 있으며 텍스처 표류가 발생함"
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "배경 여성의 손 움직임 이상과 화자의 입/치아 왜곡 아티팩트로 대상과 현상이 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "배경의 마우스를 쥔 손의 움직임 이상과 화면 하단 손의 왜곡 및 블렌딩 현상은 대상과 현상이 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "배경 여성의 손 움직임 이상과 화자의 입 주변 모핑 결함으로 대상과 결함이 전혀 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "배경 인물의 손이 이상하게 움직인다는 내용과 배경 인물들이 부자연스럽게 정지해 있다는 내용은 서로 상반되며 대상 현상이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "의미 없는 발화 내용(음성/대사 이상)과 발화 시 입/치아의 시각적 왜곡 결함은 대상 및 결함 내용이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "의미 없는 말을 한다는 대사 결함과 화면 하단 손의 왜곡 결함은 전혀 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "의미 없는 단어들을 말한다는 음성/대사 관련 이상과 입술 및 치아 주변의 시각적 워핑 결함은 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "말하는 내용의 이상과 배경 인물들의 비정상적인 정지 상태는 대상과 현상이 완전히 다릅니다."
    }
  ]
}
